%{
const defaultVehicleNimbleness = Number(entity.system.props.VNIMBLENESS ?? 1);
const fd = await foundry.applications.api.DialogV2.input({
  window: { title: "Driving Skill Test" },
content:
  '<p><strong>Enter the vehicle\'s Nimbleness:</strong></p>' +
  '<input ' +
    'name="vehicleNimbleness" ' +
    'type="number" ' +
    'min="0" ' +
    'max="6" ' +
    'step="1" ' +
    'value="' + defaultVehicleNimbleness + '" ' +
    'autofocus ' +
    'style="width:60px; text-align:center;"' +
  '>',
  ok: {
    label: "FANG IT!"
  }
});

if (!fd) return;

const vehicleNimbleness = Number(fd.vehicleNimbleness ?? 0);
const driverNimbleness = Number(entity.system.props.Nimbleness ?? 0);
const pool = Math.min(driverNimbleness, vehicleNimbleness);

return await game.macros.getName('V6 Roll Engine').execute({
  pool: pool,
  name: 'Driving Skill Test',
  skill: ${Drive}$,
  props: entity.system.props
});
}%

%{
const item = entity;
const actor = item.parent;

if (!actor || actor.documentName !== "Actor") {
  ui.notifications.warn("This mutation is not attached to a character.");
  return;
}

const attributeMap = {
  MUSCLE: "Muscle",
  UNDERSTANDING: "Understanding",
  TENACITY: "Tenacity",
  APPEAL: "Appeal",
  NIMBLENESS: "Nimbleness",
  TOUGHNESS: "Toughness",
  SENSES: "Senses"
};

const attributeChoice = item.system.props.MRATT;
const skillKey = item.system.props.MRSKL;

const attributeKey = attributeMap[attributeChoice];

if (!attributeKey) {
  ui.notifications.warn("No valid Attribute is selected for this mutation.");
  return;
}

const attributeOverride = item.system.props.MRATTO;

let pool;
let autoSuccesses = 0;

if (attributeOverride === "CHARACTER'S") {
  pool = Number(actor.system.props[attributeKey] ?? 0);
} else if (Number(attributeOverride) === 6) {
  pool = 5;
  autoSuccesses = 1;
} else {
  pool = Number(attributeOverride);
}

const skillOverride = item.system.props.MSKILLO;

const skill = skillOverride === "CHARACTER'S"
  ? Number(actor.system.props[skillKey] ?? 0)
  : Number(skillOverride);

return await game.macros.getName("V6 Roll Engine").execute({
  pool: pool,
  autoSuccesses: autoSuccesses,
  name: item.name,
  skill: skill,
  props: actor.system.props,
  actorId: actor.id,
  baseDamage: 0,
  damageType: ""
});
}%

