%{
const item = entity;

const vehicle =
  item.parent?.documentName === "Actor"
    ? item.parent
    : null;

const operatorId =
  vehicle?.getFlag("world", "v6GarageOperator");

const actor =
  operatorId
    ? game.actors.get(operatorId)
    : null;

const isUnattached = !vehicle;

if (vehicle && !actor) {
  ui.notifications.warn(
    `${vehicle.name} has no current Garage operator.`
  );
  return;
}

const attributeMap = {
  M: "Muscle",
  N: "Nimbleness",
  U: "Understanding"
};

const attributeKey =
  attributeMap[item.system.props.ATT ?? "M"];

const skillKey = item.system.props.SKL;

let attributeValue;
let skill;
let muscleValue;
let rollProps;
let actorId = null;


// ----- GARAGE OPERATOR -----

if (actor) {
  attributeValue =
    Number(actor.system?.props?.[attributeKey] ?? 0);

  skill =
    Number(actor.system?.props?.[skillKey] ?? 0);

  muscleValue =
    Number(actor.system?.props?.Muscle ?? 0);

  rollProps = actor.system.props;
  actorId = actor.id;
}


// ----- UNATTACHED VEHICLE WEAPON -----

else if (isUnattached) {
  const needsSeparateMuscle =
    item.system.props.AddMuscle &&
    attributeKey !== "Muscle";

  const content = `
    <form>
      <div class="form-group">
        <label>${attributeKey}</label>
        <input
          type="number"
          name="attributeValue"
          value="0"
          min="0">
      </div>

      <div class="form-group">
        <label>${skillKey}</label>
        <input
          type="number"
          name="skillValue"
          value="0"
          min="0">
      </div>

      ${
        needsSeparateMuscle
          ? `
            <div class="form-group">
              <label>Muscle (+M Damage)</label>
              <input
                type="number"
                name="muscleValue"
                value="0"
                min="0">
            </div>
          `
          : ""
      }
    </form>
  `;

  const values = await Dialog.prompt({
    title: `${item.name} — Unattached Vehicle Weapon`,
    content: content,
    label: "Fire",

    callback: html => {
      return {
        attribute: Number(
          html.find('[name="attributeValue"]').val() ?? 0
        ),

        skill: Number(
          html.find('[name="skillValue"]').val() ?? 0
        ),

        muscle: needsSeparateMuscle
          ? Number(
              html.find('[name="muscleValue"]').val() ?? 0
            )
          : null
      };
    }
  });

  if (!values) return;

  attributeValue = values.attribute;
  skill = values.skill;

  muscleValue =
    attributeKey === "Muscle"
      ? attributeValue
      : Number(values.muscle ?? 0);

  rollProps = {
    [attributeKey]: attributeValue,
    [skillKey]: skill,
    Muscle: muscleValue
  };
}


// ----- BUILD ROLL -----

const aimBonus =
  Number(item.system.props.AIMCNT ?? 0);

const autoSuccesses =
  Math.max(0, attributeValue - 5);

const pool =
  Math.min(attributeValue, 5) + aimBonus;

let baseDamage =
  Number(item.system.props.DMG ?? 0);

if (item.system.props.AddMuscle) {
  baseDamage += muscleValue;
}


// ----- AMMUNITION -----

const currentAmmo =
  Number(item.system.props.CurAmmo ?? 0);

const capacity =
  Number(item.system.props.Cap ?? 0);

const usesAmmo = capacity > 0;

const reloadCounter =
  Number(item.system.props.RLDCNT ?? 0);

if (reloadCounter > 0) {
  ui.notifications.warn(
    `${item.name} is still reloading — ${reloadCounter} reload Action${reloadCounter === 1 ? "" : "s"} remain before it can fire.`
  );
  return;
}

if (usesAmmo && currentAmmo <= 0) {
  ui.notifications.warn("CLICK — OUT OF AMMO");
  return;
}

if (usesAmmo && currentAmmo > 0) {
  await item.update({
    "system.props.CurAmmo": currentAmmo - 1
  });
}

await item.update({
  "system.props.AIMCNT": 0
});


// ----- ROLL -----

return await game.macros.getName("V6 Roll Engine").execute({
  pool: pool,
  autoSuccesses: autoSuccesses,
  name: item.name,
  skill: skill,
  props: rollProps,
  actorId: actorId,
  baseDamage: baseDamage,
  damageType: item.system.props.Leth ? "L" : "N"
});
}%

