%{
const item = entity;

const actor =
  item.parent?.documentName === "Actor"
    ? item.parent
    : null;

const isUnattached = !actor;

const capacity =
  Number(item.system.props.Cap ?? 0);

const currentAmmo =
  Number(item.system.props.CurAmmo ?? 0);

const reloadTime =
  Number(item.system.props.Rld ?? 0);

const reloadCounter =
  Number(item.system.props.RLDCNT ?? 0);

const usesLocalAmmo =
  Boolean(item.system.props.LAMO);

const newReloadCounter =
  reloadCounter > 0
    ? reloadCounter - 1
    : Math.max(reloadTime - 1, 0);


// ----- RESERVE AMMO SOURCE -----

const ammoKey =
  String(item.system.props.ATP ?? "")
    .replace(/^D/, "");

const ammoNameMap = {
  DLHA: "Light Handgun / SMG",
  DMHA: "Medium Handgun / SMG",
  DHHA: "Heavy Handgun / SMG",
  DLRA: "Light Rifle / MG",
  DMRA: "Medium Rifle / MG",
  DHRA: "Heavy Rifle / MG",
  DSHA: "Shotgun",
  DABA: "Arrows"
};

const ammoName =
  usesLocalAmmo
    ? "local"
    : (ammoNameMap[item.system.props.ATP]
       ?? item.system.props.ATP);

// Local Ammo uses the weapon's own reserve.
//
// Standard ammo on an attached weapon uses
// the character's reserve.
//
// Standard ammo on an unattached weapon is
// unlimited "ghost ammo" for testing.
const reserveAmmo =
  usesLocalAmmo
    ? Number(item.system.props.LocalAmmo ?? 0)
    : isUnattached
      ? Infinity
      : Number(actor.system.props[ammoKey] ?? 0);


// ----- OUT OF RESERVE AMMO -----

if (reserveAmmo <= 0) {
  await ChatMessage.create({
    user: game.user.id,
    content: `
      <div class="v6-card">
        <h2>OH SHEET! OUT OF AMMO.</h2>
        <p><strong>${item.name}</strong> has no ${ammoName} ammo available.</p>
      </div>
    `
  });

  return;
}


// ----- ALREADY FULL -----

if (currentAmmo >= capacity) {
  if (reloadCounter > 0) {
    await item.update({
      "system.props.RLDCNT": 0
    });
  }

  ui.notifications.info(
    `${item.name} is already fully loaded.`
  );

  return;
}


// ----- ADVANCE RELOAD -----

await item.update({
  "system.props.RLDCNT": newReloadCounter,
  "system.props.AIMCNT": 0
});

const reloaderName =
  actor?.name ?? "Someone";

await ChatMessage.create({
  user: game.user.id,

  speaker: actor
    ? ChatMessage.getSpeaker({ actor })
    : ChatMessage.getSpeaker(),

  content: `
    <div class="v6-card">
      <h2>${item.name} — RELOAD</h2>

      ${
        newReloadCounter > 0
          ? `<p>${reloaderName} spends an Action reloading.</p>
             <p><strong>${newReloadCounter}</strong> reload Action${newReloadCounter === 1 ? "" : "s"} remain before you can fire this weapon.</p>`

          : `<p>${reloaderName} finishes reloading. Weapon will be ready to fire next Action.</p>`
      }
    </div>
  `
});


// ----- LOAD AMMUNITION -----

if (newReloadCounter === 0) {

  const needed =
    Math.max(0, capacity - currentAmmo);

  const roundsToLoad =
    isUnattached && !usesLocalAmmo
      ? needed
      : Math.min(needed, reserveAmmo);

  // Load the magazine.
  await item.update({
    "system.props.CurAmmo":
      currentAmmo + roundsToLoad,

    "system.props.AIMCNT": 0
  });

  // Local Ammo consumes the weapon's own reserve.
  if (usesLocalAmmo) {
    await item.update({
      "system.props.LocalAmmo":
        reserveAmmo - roundsToLoad
    });
  }

  // Attached standard ammo consumes the
  // character's reserve.
  else if (!isUnattached) {
    await actor.update({
      [`system.props.${ammoKey}`]:
        reserveAmmo - roundsToLoad
    });
  }

  // Unattached + standard ammo:
  // deduct nothing. Ghost bullets.
}
}%

